package com.onrender.smartnf.web;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import org.springframework.web.server.ResponseStatusException;
import java.net.URI;import java.net.http.*;import java.nio.ByteBuffer;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.Flow.*;
import tools.jackson.databind.json.JsonMapper;
class GeminiPeriodClientTests {
 static final String OK="{\"candidates\":[{\"finishReason\":\"STOP\",\"content\":{\"parts\":[{\"text\":\"private thought\",\"thought\":true},{\"text\":\"{\\\"newRecipes\\\":[],\\\"slots\\\":[]}\"}]}}]}";
 record Reply(int statusCode,String body,HttpRequest request)implements HttpResponse<String>{public Optional<HttpResponse<String>> previousResponse(){return Optional.empty();}public HttpHeaders headers(){return HttpHeaders.of(Map.of(),(a,b)->true);}public Optional<javax.net.ssl.SSLSession> sslSession(){return Optional.empty();}public URI uri(){return request.uri();}public HttpClient.Version version(){return HttpClient.Version.HTTP_1_1;}}
 static String body(HttpRequest request){var result=new CompletableFuture<String>();var bytes=new java.io.ByteArrayOutputStream();request.bodyPublisher().orElseThrow().subscribe(new Subscriber<ByteBuffer>(){public void onSubscribe(Subscription s){s.request(Long.MAX_VALUE);}public void onNext(ByteBuffer b){byte[] value=new byte[b.remaining()];b.get(value);bytes.writeBytes(value);}public void onError(Throwable e){result.completeExceptionally(e);}public void onComplete(){result.complete(bytes.toString(StandardCharsets.UTF_8));}});return result.join();}
 static String error(String message){return new JsonMapper().writeValueAsString(Map.of("error",Map.of("message",message,"status","INVALID_ARGUMENT")));}
 @Test void successUsesFixedEndpointHeadersAndStrippedSchema(){List<HttpRequest> sent=new ArrayList<>();var client=new GeminiPeriodClient("not-a-real-key","gemini-3.5-flash-lite",r->{sent.add(r);return new Reply(200,OK,r);});assertEquals("{\"newRecipes\":[],\"slots\":[]}",client.generate("{}",GeminiPeriodService.schema()));var r=sent.getFirst();assertEquals("generativelanguage.googleapis.com",r.uri().getHost());assertEquals("not-a-real-key",r.headers().firstValue("x-goog-api-key").orElseThrow());assertTrue(r.timeout().orElseThrow().compareTo(Duration.ofSeconds(75))<=0);assertFalse(body(r).contains("maxItems"));assertFalse(body(r).contains("private thought"));}
 @Test void confirmedSchemaRejectionRetriesOnceAsJsonAndKeepsInput(){var sent=new ArrayList<HttpRequest>();var client=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->{sent.add(r);return new Reply(sent.size()==1?400:200,sent.size()==1?error("responseSchema too many states"):OK,r);});client.generate("{\"first\":\"2027-02-01\"}",GeminiPeriodService.schema());assertEquals(2,sent.size());var json=new JsonMapper();var next=json.readTree(body(sent.getLast()));assertFalse(next.path("generationConfig").has("responseSchema"));assertEquals(8192,next.path("generationConfig").path("maxOutputTokens").asInt());assertTrue(body(sent.getLast()).contains("2027-02-01"));assertTrue(sent.getLast().timeout().orElseThrow().compareTo(sent.getFirst().timeout().orElseThrow())<0);}
 @Test void tokenParameterRejectionHasSameBoundedCompatibilityPath(){int[] calls={0};var client=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->new Reply(++calls[0]==1?400:200,calls[0]==1?error("max_output_tokens limit exceeded"):OK,r));client.generate("{}",GeminiPeriodService.schema());assertEquals(2,calls[0]);}
 @Test void noRetryForKeyPermissionModelQuotaOrServerErrors(){for(var sample:List.of(new Object[]{400,"API key not valid secret","API_KEY"},new Object[]{400,"API key not valid for responseSchema secret","API_KEY"},new Object[]{403,"permission denied secret","PERMISSION"},new Object[]{404,"model missing secret","MODEL_NOT_FOUND"},new Object[]{429,"quota secret","QUOTA"},new Object[]{503,"unavailable secret","UPSTREAM_UNAVAILABLE"},new Object[]{400,"bad unrelated input secret","INVALID_REQUEST"})){int[] calls={0};int status=(int)sample[0];var client=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->{calls[0]++;return new Reply(status,error((String)sample[1]),r);});var e=assertThrows(ResponseStatusException.class,()->client.generate("{}",GeminiPeriodService.schema()));assertEquals(1,calls[0]);assertTrue(e.getReason().contains("HTTP "+status));assertTrue(e.getReason().contains("GEMINI_"+sample[2]));assertFalse(e.getReason().contains("secret"));}}
 @Test void secondRejectionStopsAndReturnsSafeReason(){int[] calls={0};var client=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->{calls[0]++;return new Reply(400,error("responseSchema too complex secret"),r);});assertTrue(assertThrows(ResponseStatusException.class,()->client.generate("{}",GeminiPeriodService.schema())).getReason().contains("GEMINI_INVALID_REQUEST"));assertEquals(2,calls[0]);}
 @Test void timeoutsAndTruncationAreDistinct(){var timeout=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->{throw new HttpTimeoutException("secret");});assertTrue(assertThrows(ResponseStatusException.class,()->timeout.generate("{}",GeminiPeriodService.schema())).getReason().contains("GEMINI_TIMEOUT"));var truncated=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->new Reply(200,OK.replace("STOP","MAX_TOKENS"),r));assertTrue(assertThrows(ResponseStatusException.class,()->truncated.generate("{}",GeminiPeriodService.schema())).getReason().contains("GEMINI_OUTPUT_LIMIT"));}
 @Test void invalidModelOrEmptyKeyNeverSends(){int[] calls={0};var client=new GeminiPeriodClient("","gemini-3.5-flash-lite",r->{calls[0]++;return new Reply(200,OK,r);});assertThrows(ResponseStatusException.class,()->client.generate("{}",GeminiPeriodService.schema()));var other=new GeminiPeriodClient("secret","http://attacker",r->{calls[0]++;return new Reply(200,OK,r);});assertThrows(ResponseStatusException.class,()->other.generate("{}",GeminiPeriodService.schema()));assertEquals(0,calls[0]);}

 @Test void compositionRepairSharesDeadlineAcrossGenerateCallsAndClearsScope(){
  var sent=new ArrayList<HttpRequest>();var client=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->{sent.add(r);return new Reply(200,OK,r);});
  client.withinRecommendation(()->{client.generate("{}",GeminiPeriodService.schema());try{Thread.sleep(30);}catch(InterruptedException e){throw new RuntimeException(e);}return client.generate("{}",GeminiPeriodService.schema());});
  assertTrue(sent.get(1).timeout().orElseThrow().compareTo(sent.get(0).timeout().orElseThrow().minusMillis(15))<0);
  client.generate("{}",GeminiPeriodService.schema());assertTrue(sent.get(2).timeout().orElseThrow().compareTo(sent.get(1).timeout().orElseThrow())>0);
 }
 @Test void deadlineScopeIsClearedAfterFailure(){
  var sent=new ArrayList<HttpRequest>();var client=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->{sent.add(r);return new Reply(200,OK,r);});
  assertThrows(IllegalStateException.class,()->client.withinRecommendation(()->{client.generate("{}",GeminiPeriodService.schema());try{Thread.sleep(30);}catch(InterruptedException e){throw new RuntimeException(e);}throw new IllegalStateException();}));
  client.generate("{}",GeminiPeriodService.schema());assertTrue(sent.getLast().timeout().orElseThrow().compareTo(Duration.ofSeconds(75).minusMillis(15))>0);
 }

 @Test void jsonCompatibilityFallbackAlsoSpecifiesExplicitComponents(){
  var sent=new ArrayList<HttpRequest>();var client=new GeminiPeriodClient("secret","gemini-3.5-flash-lite",r->{sent.add(r);return new Reply(sent.size()==1?400:200,sent.size()==1?error("responseSchema too complex"):OK,r);});client.generate("{}",GeminiPeriodService.schema());String instructions=new JsonMapper().readTree(body(sent.getLast())).path("systemInstruction").path("parts").path(0).path("text").asText();assertTrue(instructions.contains("\"composition\""));assertTrue(instructions.contains("stapleRecipeId"));assertTrue(instructions.contains("sideRecipeIds"));assertTrue(instructions.contains("center.role이 bowl"));
 }
}
